// Success response with CORS headers
msg.statusCode = 200;
msg.headers = {
    'Access-Control-Allow-Origin': 'https://scanner.tudublinattendanceproject.com',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'content-type, cf-access-authenticated-user-email, authorization',
    'Access-Control-Allow-Credentials': 'true'
};
msg.payload = {
    success: true,
    message: 'Check-in successful',
    studentId: msg.payload.studentId || msg.authenticatedStudentId,
    roomId: msg.payload.roomId,
    action: msg.payload.action
};
return msg;
